import { randomUUID } from "node:crypto";
import {
  VideoResearchError,
  normalizeYouTubeVideoId,
  type VideoResearchProvider,
  type VideoSearchResult,
  type VideoTranscript,
  type VideoTranscriptOptions,
  type VideoTranscriptSegment,
} from "./VideoResearchContracts";

function requestId(prefix: string): string {
  return prefix + "_" + randomUUID().slice(0, 8);
}

function retryable(status: number): boolean {
  return status === 408 || status === 425 || status === 429 || status >= 500;
}

async function jsonRequest<T>(
  providerId: string,
  input: RequestInfo | URL,
  init: RequestInit,
): Promise<{ data: T; status: number; requestId: string }> {
  const responseId = requestId(providerId.toLowerCase());
  try {
    const response = await fetch(input, init);
    const body = await response.text();

    if (!response.ok) {
      throw new VideoResearchError(
        providerId,
        providerId + " returned HTTP " + response.status + (body ? ": " + body.slice(0, 500) : ""),
        { status: response.status, retryable: retryable(response.status) },
      );
    }

    try {
      return {
        data: JSON.parse(body) as T,
        status: response.status,
        requestId: responseId,
      };
    } catch {
      throw new VideoResearchError(
        providerId,
        providerId + " returned non-JSON data.",
      );
    }
  } catch (error) {
    if (error instanceof VideoResearchError) throw error;
    throw new VideoResearchError(
      providerId,
      error instanceof Error ? error.message : String(error),
      { retryable: true },
    );
  }
}

function segmentsFromArcmira(lines: any[]): VideoTranscriptSegment[] {
  return lines.flatMap((line: any) => {
    if (typeof line?.text !== "string" || !line.text.trim()) return [];
    const start = Number(line?.start ?? 0);
    const end = Number(line?.end);
    const duration =
      Number.isFinite(end) && end >= start
        ? end - start
        : Number(line?.duration ?? 0);
    return [{
      startSeconds: Number.isFinite(start) ? start : 0,
      durationSeconds: Number.isFinite(duration) && duration >= 0 ? duration : 0,
      text: line.text.trim(),
    }];
  });
}

function segmentsFromGeneric(value: any): VideoTranscriptSegment[] {
  const list = Array.isArray(value) ? value : [];
  return list.flatMap((segment: any) => {
    if (typeof segment?.text !== "string" || !segment.text.trim()) return [];
    const start = Number(segment?.start ?? segment?.startSeconds ?? 0);
    const duration = Number(
      segment?.duration ?? segment?.durationSeconds ?? 0,
    );
    return [{
      startSeconds: Number.isFinite(start) && start >= 0 ? start : 0,
      durationSeconds: Number.isFinite(duration) && duration >= 0 ? duration : 0,
      text: segment.text.trim(),
    }];
  });
}

function joinSegments(segments: readonly VideoTranscriptSegment[]): string {
  return segments.map((segment) => segment.text).join(" ").trim();
}

function sourceKind(
  source: unknown,
  autoGenerated: unknown,
): VideoTranscript["sourceKind"] {
  const value = typeof source === "string" ? source.toLowerCase() : "";
  if (value.includes("speech")) return "SPEECH_TO_TEXT";
  if (value.includes("caption")) {
    return autoGenerated ? "AUTO_CAPTIONS" : "CREATOR_CAPTIONS";
  }
  return "UNKNOWN";
}

export class ArcmiraVideoProvider implements VideoResearchProvider {
  readonly id = "arcmira";
  readonly capabilities = ["TRANSCRIPT", "VIDEO_SEARCH"] as const;
  private readonly apiKey = process.env.ARCMIRA_API_KEY?.trim() || "";

  async search(query: string, count = 5): Promise<readonly VideoSearchResult[]> {
    if (!this.apiKey) return [];
    const url = new URL("https://api.arcmira.com/v1/transcripts/search");
    url.searchParams.set("q", query);
    url.searchParams.set("limit", String(Math.min(Math.max(count, 1), 20)));

    const result = await jsonRequest<any>(this.id, url, {
      headers: { Authorization: "Bearer " + this.apiKey, Accept: "application/json" },
    });

    const items = Array.isArray(result.data?.results)
      ? result.data.results
      : [];
    return items.slice(0, count).flatMap((item: any) => {
      const id =
        typeof item?.videoId === "string"
          ? item.videoId
          : typeof item?.video?.id === "string"
            ? item.video.id
            : "";
      if (!id) return [];
      return [{
        providerId: this.id,
        providerRequestId: result.requestId,
        videoId: id,
        sourceUrl:
          typeof item?.watchUrl === "string"
            ? item.watchUrl
            : "https://www.youtube.com/watch?v=" + id,
        title:
          typeof item?.title === "string"
            ? item.title
            : typeof item?.video?.title === "string"
              ? item.video.title
              : "Arcmira video result",
        channel:
          typeof item?.channel === "string"
            ? item.channel
            : item?.video?.channel,
        publishedAt: item?.publishDate || item?.video?.publishDate,
      }];
    });
  }

  async transcript(
    videoRef: string,
    options: VideoTranscriptOptions = {},
  ): Promise<VideoTranscript> {
    if (!this.apiKey) {
      throw new VideoResearchError(this.id, "ARCMIRA_API_KEY is not configured.");
    }
    const videoId = normalizeYouTubeVideoId(videoRef);
    const url = new URL(
      "https://api.arcmira.com/v1/transcripts/" + encodeURIComponent(videoId),
    );
    if (options.language) url.searchParams.set("language", options.language);

    const result = await jsonRequest<any>(this.id, url, {
      headers: { Authorization: "Bearer " + this.apiKey, Accept: "application/json" },
    });
    const segments = segmentsFromArcmira(result.data?.lines);
    if (!segments.length) {
      throw new VideoResearchError(this.id, "Arcmira returned no transcript lines.");
    }

    return {
      providerId: this.id,
      providerRequestId: result.requestId,
      videoId,
      sourceUrl:
        typeof result.data?.video?.watchUrl === "string"
          ? result.data.video.watchUrl
          : "https://www.youtube.com/watch?v=" + videoId,
      title: result.data?.video?.title,
      channel: result.data?.video?.channel,
      language: result.data?.language,
      autoGenerated:
        result.data?.source === "captions"
          ? Boolean(result.data?.autoGenerated)
          : undefined,
      sourceKind: sourceKind(
        result.data?.source,
        result.data?.autoGenerated,
      ),
      durationSeconds: Number(result.data?.video?.duration) || undefined,
      segments,
      text: joinSegments(segments),
      retrievedAt: new Date().toISOString(),
    };
  }

  async health(): Promise<boolean> {
    return Boolean(this.apiKey);
  }
}

export class TranscriptYTProvider implements VideoResearchProvider {
  readonly id = "transcriptyt";
  readonly capabilities = ["TRANSCRIPT"] as const;
  private readonly apiKey = process.env.TRANSCRIPT_YT_API_KEY?.trim() || "";

  async search(): Promise<readonly VideoSearchResult[]> {
    return [];
  }

  async transcript(
    videoRef: string,
    options: VideoTranscriptOptions = {},
  ): Promise<VideoTranscript> {
    if (!this.apiKey) {
      throw new VideoResearchError(
        this.id,
        "TRANSCRIPT_YT_API_KEY is not configured.",
      );
    }

    const url = new URL("https://transcript-yt.com/v1/transcript");
    url.searchParams.set("url", videoRef);
    url.searchParams.set("format", "json");
    url.searchParams.set("includeSegments", "true");
    if (options.language) url.searchParams.set("language", options.language);
    if (options.translateTo) url.searchParams.set("translate_to", options.translateTo);

    const result = await jsonRequest<any>(this.id, url, {
      headers: { Authorization: "Bearer " + this.apiKey, Accept: "application/json" },
    });
    const segments = segmentsFromGeneric(result.data?.segments);
    if (!segments.length) {
      throw new VideoResearchError(this.id, "TranscriptYT returned no transcript segments.");
    }

    const videoId =
      typeof result.data?.videoId === "string"
        ? result.data.videoId
        : normalizeYouTubeVideoId(videoRef);

    return {
      providerId: this.id,
      providerRequestId: result.requestId,
      videoId,
      sourceUrl: "https://www.youtube.com/watch?v=" + videoId,
      title: result.data?.title,
      channel: result.data?.author,
      channelId: result.data?.channelId,
      language: result.data?.language,
      translated: Boolean(result.data?.translated),
      autoGenerated:
        typeof result.data?.autoGenerated === "boolean"
          ? result.data.autoGenerated
          : undefined,
      sourceKind: sourceKind(
        result.data?.source,
        result.data?.autoGenerated,
      ),
      durationSeconds: Number(result.data?.durationSeconds) || undefined,
      segments,
      text:
        typeof result.data?.text === "string" && result.data.text.trim()
          ? result.data.text.trim()
          : joinSegments(segments),
      retrievedAt: new Date().toISOString(),
    };
  }

  async health(): Promise<boolean> {
    return Boolean(this.apiKey);
  }
}

export class VidWordsProvider implements VideoResearchProvider {
  readonly id = "vidwords";
  readonly capabilities = ["TRANSCRIPT"] as const;
  private readonly apiKey = process.env.VIDWORDS_API_KEY?.trim() || "";

  async search(): Promise<readonly VideoSearchResult[]> {
    return [];
  }

  async transcript(
    videoRef: string,
    options: VideoTranscriptOptions = {},
  ): Promise<VideoTranscript> {
    if (!this.apiKey) {
      throw new VideoResearchError(this.id, "VIDWORDS_API_KEY is not configured.");
    }
    const videoId = normalizeYouTubeVideoId(videoRef);
    const result = await jsonRequest<any>(
      this.id,
      "https://vidwords.com/api/transcripts",
      {
        method: "POST",
        headers: {
          Authorization: "Basic " + this.apiKey,
          Accept: "application/json",
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          ids: [videoId],
          ...(options.language ? { lang: options.language } : {}),
        }),
      },
    );

    const first = Array.isArray(result.data?.results)
      ? result.data.results.find((item: any) => item?.id === videoId) ||
        result.data.results[0]
      : undefined;
    if (!first || typeof first?.text !== "string") {
      throw new VideoResearchError(this.id, "VidWords returned no usable transcript result.");
    }

    const segments = segmentsFromGeneric(first?.segments);
    return {
      providerId: this.id,
      providerRequestId: result.requestId,
      videoId,
      sourceUrl: "https://www.youtube.com/watch?v=" + videoId,
      title: first?.title,
      language: options.language,
      autoGenerated: undefined,
      sourceKind: "UNKNOWN",
      segments,
      text: first.text.trim(),
      retrievedAt: new Date().toISOString(),
    };
  }

  async health(): Promise<boolean> {
    return Boolean(this.apiKey);
  }
}

export class TubeToTranscriptProvider implements VideoResearchProvider {
  readonly id = "tubetotranscript";
  readonly capabilities = ["TRANSCRIPT"] as const;
  private readonly apiKey = process.env.TUBETOTRANSCRIPT_API_KEY?.trim() || "";

  async search(): Promise<readonly VideoSearchResult[]> {
    return [];
  }

  async transcript(
    videoRef: string,
    options: VideoTranscriptOptions = {},
  ): Promise<VideoTranscript> {
    if (!this.apiKey) {
      throw new VideoResearchError(
        this.id,
        "TUBETOTRANSCRIPT_API_KEY is not configured.",
      );
    }

    const videoId = normalizeYouTubeVideoId(videoRef);
    const url = new URL("https://www.tubetotranscript.com/api/v1/transcript");
    url.searchParams.set("url", videoRef);
    if (options.language) url.searchParams.set("language", options.language);

    const result = await jsonRequest<any>(this.id, url, {
      headers: { Authorization: "Bearer " + this.apiKey, Accept: "application/json" },
    });
    const segments = segmentsFromGeneric(result.data?.transcript);
    if (!segments.length) {
      throw new VideoResearchError(this.id, "TubeToTranscript returned no transcript lines.");
    }

    return {
      providerId: this.id,
      providerRequestId: result.requestId,
      videoId:
        typeof result.data?.metadata?.videoId === "string"
          ? result.data.metadata.videoId
          : videoId,
      sourceUrl: "https://www.youtube.com/watch?v=" + videoId,
      title: result.data?.metadata?.title,
      channel: result.data?.metadata?.channel,
      language: result.data?.language,
      autoGenerated:
        typeof result.data?.is_generated === "boolean"
          ? result.data.is_generated
          : undefined,
      sourceKind:
        result.data?.is_generated === true
          ? "AUTO_CAPTIONS"
          : result.data?.is_generated === false
            ? "CREATOR_CAPTIONS"
            : "UNKNOWN",
      durationSeconds: Number(result.data?.length_seconds) || undefined,
      segments,
      text:
        typeof result.data?.text === "string" && result.data.text.trim()
          ? result.data.text.trim()
          : joinSegments(segments),
      retrievedAt: new Date().toISOString(),
    };
  }

  async health(): Promise<boolean> {
    return Boolean(this.apiKey);
  }
}

export class YouTubeDataApiProvider implements VideoResearchProvider {
  readonly id = "youtube_data_api";
  readonly capabilities = ["VIDEO_SEARCH", "VIDEO_METADATA"] as const;
  private readonly apiKey = process.env.YOUTUBE_API_KEY?.trim() || "";

  async search(
    query: string,
    count = 5,
  ): Promise<readonly VideoSearchResult[]> {
    if (!this.apiKey) return [];
    const url = new URL(
      "https://www.googleapis.com/youtube/v3/search",
    );
    url.searchParams.set("part", "snippet");
    url.searchParams.set("type", "video");
    url.searchParams.set("q", query);
    url.searchParams.set(
      "maxResults",
      String(Math.min(Math.max(count, 1), 50)),
    );
    url.searchParams.set("key", this.apiKey);

    const result = await jsonRequest<any>(this.id, url, {
      headers: { Accept: "application/json" },
    });
    const items = Array.isArray(result.data?.items) ? result.data.items : [];

    return items.flatMap((item: any) => {
      const id =
        typeof item?.id?.videoId === "string" ? item.id.videoId : "";
      if (!id) return [];
      return [{
        providerId: this.id,
        providerRequestId: result.requestId,
        videoId: id,
        sourceUrl: "https://www.youtube.com/watch?v=" + id,
        title:
          typeof item?.snippet?.title === "string"
            ? item.snippet.title
            : "YouTube video",
        channel: item?.snippet?.channelTitle,
        channelId: item?.snippet?.channelId,
        description: item?.snippet?.description,
        publishedAt: item?.snippet?.publishedAt,
        thumbnailUrl: item?.snippet?.thumbnails?.high?.url ||
          item?.snippet?.thumbnails?.default?.url,
      }];
    });
  }

  async health(): Promise<boolean> {
    return Boolean(this.apiKey);
  }
}
